(6300171, 932108, 124815, '<td valign="top">I keep coming back to your picture. Chekhovian. I am missing something though. It looks just a touch flat like a constructed stage set before the lighting designer''s touch. Nevertheless, top 10 for me.</td>', 'I keep coming back to your picture. Chekhovian. I am missing something though. It looks just a touch flat like a constructed stage set before the lighting designer''s touch. Nevertheless, top 10 for me.', '2011-02-01 19:45:24.000000', NULL, 1),
(6300172, 927520, 124815, '<td valign="top">I heard this sweet voice before! No, no visits. I just take a lot of pleasure looking at you from the distance. Top 10.</td>', 'I heard this sweet voice before! No, no visits. I just take a lot of pleasure looking at you from the distance. Top 10.', '2011-02-01 19:47:22.000000', NULL, 1),
(6300176, 931055, 124815, '<td valign="top">Very nice and refreshing to see the back of a cat after all the landscapes (and I do not say pejoratively "landscapes" since some are stunning) and portraits.</td>', 'Very nice and refreshing to see the back of a cat after all the landscapes (and I do not say pejoratively "landscapes" since some are stunning) and portraits.', '2011-02-01 19:54:33.000000', NULL, 1),
(6300177, 933128, 124815, '<td valign="top">One of the best portraits of the challenge</td>', 'One of the best portraits of the challenge', '2011-02-01 19:55:32.000000', NULL, 1),
(6300178, 932819, 124815, '<td valign="top">Came back to upgrade your picture that stuck to my mind. Looks like a music score and I almost can hear the cicadas. Or frogs! I imagine it still continuing to the right, endlessly. Beautiful! Top 10.</td>', 'Came back to upgrade your picture that stuck to my mind. Looks like a music score and I almost can hear the cicadas. Or frogs! I imagine it still continuing to the right, endlessly. Beautiful! Top 10.', '2011-02-01 19:57:53.000000', NULL, 1),
(6300182, 932708, 124815, '<td valign="top">Oh, I feel your pain! I wished for a different silhouette, unless it''s a candid shot. The ceiling makes all work. Beautiful.</td>', 'Oh, I feel your pain! I wished for a different silhouette, unless it''s a candid shot. The ceiling makes all work. Beautiful.', '2011-02-01 20:00:52.000000', NULL, 1),
(6300186, 932710, 124815, '<td valign="top">My second most favorite portrait of the challenge. Has the air of a waif who just got a part in a marionette show. A Piaf look alike. Very nice.</td>', 'My second most favorite portrait of the challenge. Has the air of a waif who just got a part in a marionette show. A Piaf look alike. Very nice.', '2011-02-01 20:02:55.000000', NULL, 1),
(6300187, 932768, 124815, '<td valign="top">I am glad that I did not see this picture in the "Sentinel" challenge. It makes perfect sense here. Very nice.</td>', 'I am glad that I did not see this picture in the "Sentinel" challenge. It makes perfect sense here. Very nice.', '2011-02-01 20:04:02.000000', NULL, 1),
(6300189, 931028, 124815, '<td valign="top">Is this a relative of a barn owl? very nice.</td>', 'Is this a relative of a barn owl? very nice.', '2011-02-01 20:05:30.000000', NULL, 1),
(6300202, 930396, 31597, '<td valign="top">Love this photo!<br/> <br/>However, I gave it a lower score than I wanted for these reasons:<br/> <br/>In editing, the whites in the snow were over-blown white bumping up the contrast/brightness. This is bad because the white over takes the snow on his face. The whites need to be even.<br/> <br/>I like the horizontal orientation but I feel it needs to be taller to complement the long shape of the dog''s face.<br/> <br/>-7</td>', 'Love this photo! However, I gave it a lower score than I wanted for these reasons: In editing, the whites in the snow were over-blown white bumping up the contrast/brightness. This is bad because the white over takes the snow on his face. The whites need to be even. I like the horizontal orientation but I feel it needs to be taller to complement the long shape of the dog''s face. -7', '2011-02-01 20:14:53.000000', NULL, 1),
