(6302460, 929817, 108580, '<td valign="top">Nice subject for HDR but the haloing needs to be controlled. Good but not perfect.</td>', 'Nice subject for HDR but the haloing needs to be controlled. Good but not perfect.', '2011-02-03 23:25:42.000000', NULL, 1),
(6302463, 930552, 108580, '<td valign="top">Devastating, Brisbane? Superb PJ image but with an artistic angle. The tower sticking through is also well composed.</td>', 'Devastating, Brisbane? Superb PJ image but with an artistic angle. The tower sticking through is also well composed.', '2011-02-03 23:28:41.000000', NULL, 1),
(6302503, 933011, 86218, '<td valign="top">Wow wow wow. This is just to unreal and special. Havent gone through all the voting and was just thinking Im not overly impressed..untill my eye caught this image. So far my blue. Im never going to get over this shot. I want a shot like this and experience this place. Im in tears. Onto my Fav list 10</td>', 'Wow wow wow. This is just to unreal and special. Havent gone through all the voting and was just thinking Im not overly impressed..untill my eye caught this image. So far my blue. Im never going to get over this shot. I want a shot like this and experience this place. Im in tears. Onto my Fav list 10', '2011-02-04 01:23:58.000000', NULL, 1),
(6302580, 931705, 86218, '<td valign="top">Magical mood here. Nice framing and comp. White lining a bit strong on the frame and dont think the pic needs this much. Good enough scene as is</td>', 'Magical mood here. Nice framing and comp. White lining a bit strong on the frame and dont think the pic needs this much. Good enough scene as is', '2011-02-04 06:28:06.000000', NULL, 1),
(6302582, 932649, 86218, '<td valign="top">Speechless. Lovely shot.</td>', 'Speechless. Lovely shot.', '2011-02-04 06:33:56.000000', NULL, 1),
(6302583, 930749, 86218, '<td valign="top">HDR suits this and colours are great. Nice comp and well seen.</td>', 'HDR suits this and colours are great. Nice comp and well seen.', '2011-02-04 06:36:39.000000', NULL, 1),
(6302584, 932989, 86218, '<td valign="top">And the eyes really need to be sharp. Missing that in this shot. Great moment with these guys sitting like this but a pity about the focus</td>', 'And the eyes really need to be sharp. Missing that in this shot. Great moment with these guys sitting like this but a pity about the focus', '2011-02-04 06:39:36.000000', NULL, 1),
(6302587, 933004, 86218, '<td valign="top">Well known scene and well composed. 2 things bothering me a bit in this scene. Clouds are a bit soft for it to work in this as a dreamlike landscape and becomes to mushy and dark to the top left. The colours Im not sure about as this has gone a bit beyond the natural "believeble" which is important for a scene like this. Would like to know if this is really what it looked like or if this is simply filters and pp</td>', 'Well known scene and well composed. 2 things bothering me a bit in this scene. Clouds are a bit soft for it to work in this as a dreamlike landscape and becomes to mushy and dark to the top left. The colours Im not sure about as this has gone a bit beyond the natural "believeble" which is important for a scene like this. Would like to know if this is really what it looked like or if this is simply filters and pp', '2011-02-04 06:49:34.000000', NULL, 1),
(6302591, 931437, 86218, '<td valign="top">It''s a nice abstract but the contrast and colours really needs working to emphasise lines &amp; light here. Placement of the focused growth point also needs to be moved a bit to left. A delicate shot which with slight adjustments would be in my tatse for a 10 vote from me. 6 now</td>', 'It''s a nice abstract but the contrast and colours really needs working to emphasise lines & light here. Placement of the focused growth point also needs to be moved a bit to left. A delicate shot which with slight adjustments would be in my tatse for a 10 vote from me. 6 now', '2011-02-04 07:00:34.000000', NULL, 1),
