(6304228, 931794, 86218, '<td valign="top">Beautiful clean shot and well composed. Pity about eyes here I need eye contact for this to be that 1 step above. 7</td>', 'Beautiful clean shot and well composed. Pity about eyes here I need eye contact for this to be that 1 step above. 7', '2011-02-06 11:40:36.000000', NULL, 1),
