(6304230, 933012, 86218, '<td valign="top">Lovely shot but I do think this needs to have more depth. F/g is blurred and for this type of shot I would love to have seen crispness throughout the frame. Still a nice take</td>', 'Lovely shot but I do think this needs to have more depth. F/g is blurred and for this type of shot I would love to have seen crispness throughout the frame. Still a nice take', '2011-02-06 11:48:43.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6304231, 931226, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: This has the quality of watercolour on parchment (I think that is interesting). Looking at the quality of the rendition, it is easy to overlook the subject matter which is, of course, compelling. I particularly like the way the small birds seem to bleed into the background. I also like your composition / framing which I think is bang-on.<br/> <br/>Critical stuff: Nothing really.<br/> <br/>Overall: Very nice picture.</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: This has the quality of watercolour on parchment (I think that is interesting). Looking at the quality of the rendition, it is easy to overlook the subject matter which is, of course, compelling. I particularly like the way the small birds seem to bleed into the background. I also like your composition / framing which I think is bang-on. Critical stuff: Nothing really. Overall: Very nice picture.', '2011-02-06 11:51:07.000000', NULL, 1),
(6304235, 928758, 3585, '<td valign="top">Inspiring image.<br/>Title a tad disconcerting.</td>', 'Inspiring image.Title a tad disconcerting.', '2011-02-06 12:04:09.000000', NULL, 1),
(6304246, 933037, 100393, '<td valign="top">I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images. <br/> <br/>Positives: An image that startles with its quality. I don''t use the word lightly. We often get some decent bird offering in the Free Study but this offers something above and beyond that sort of work. I got the blue ribbon for ''Portrait of a Wild Bird'' 13 months ago and this image is soooooo much better in every way to that offering. Difficult to make an effective comment on work such as this without just trotting out superlatives but I''ll try. The lighting (just a flash?) works so well, isolating and emphasising the gull, the focus is nailed but more than that, the smoothness of the image is outstanding. I''ll be interested to see what sensor you are using, in my work I only get this look using a full frame camera. I also wonder whether you used the Adamus sharpening technique; again it seems to offer a degree of smoothness I can''t seem to manage by other routes. The contrast you have offered between the vibrant yellow beak and eyes and the colour-monochrome of the feathers is so effective. Your model too has performed beautifully, offering up an intent quizzical look.<br/> <br/>Critical stuff: Ummm..... No.<br/> <br/>Overall: Simply outstanding - I hope you ribbon (and with an 8+ score).</td>', 'I''m going through the entries, stopping at those images I feel have had the benefit of an unconventional eye and dwelling a little longer to try to see and appreciate what you saw. This is one of those images.  Positives: An image that startles with its quality. I don''t use the word lightly. We often get some decent bird offering in the Free Study but this offers something above and beyond that sort of work. I got the blue ribbon for ''Portrait of a Wild Bird'' 13 months ago and this image is soooooo much better in every way to that offering. Difficult to make an effective comment on work such as this without just trotting out superlatives but I''ll try. The lighting (just a flash?) works so well, isolating and emphasising the gull, the focus is nailed but more than that, the smoothness of the image is outstanding. I''ll be interested to see what sensor you are using, in my work I only get this look using a full frame camera. I also wonder whether you used the Adamus sharpening technique; again it seems to offer a degree of smoothness I can''t seem to manage by other routes. The contrast you have offered between the vibrant yellow beak and eyes and the colour-monochrome of the feathers is so effective. Your model too has performed beautifully, offering up an intent quizzical look. Critical stuff: Ummm..... No. Overall: Simply outstanding - I hope you ribbon (and with an 8+ score).', '2011-02-06 12:31:11.000000', NULL, 1),
(6304274, 933033, 86218, '<td valign="top">Beautiful. What a sight. Well done with this image</td>', 'Beautiful. What a sight. Well done with this image', '2011-02-06 13:21:41.000000', NULL, 1),
(6304326, 932404, 30364, '<td valign="top">Absurd.  I like that.  Thanks.</td>', 'Absurd.  I like that.  Thanks.', '2011-02-06 14:47:02.000000', NULL, 1),
(6304329, 931035, 30364, '<td valign="top">Nice tones and fascinating lines.  Sometimes (often) omitting detail amplifies the picture.  This is one of those.  Thank you.</td>', 'Nice tones and fascinating lines.  Sometimes (often) omitting detail amplifies the picture.  This is one of those.  Thank you.', '2011-02-06 14:49:31.000000', NULL, 1),
