(6306093, 928758, 54645, '<td valign="top">Beautiful, hazed reflection of a dream. Must be a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=11769" rel="nofollow" target="_blank">jmritz</a>, if not, well done!</td>', 'Beautiful, hazed reflection of a dream. Must be a  jmritz, if not, well done!', '2011-02-07 22:33:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6306094, 933065, 30982, '<td valign="top">Sad and striking.  Wonderfully seen!</td>', 'Sad and striking.  Wonderfully seen!', '2011-02-07 22:34:13.000000', NULL, 1),
(6306101, 933029, 65234, '<td valign="top">Nice catchlights and DOF.  Not sure the negative space on the left adds much; I''d probably crop that out.</td>', 'Nice catchlights and DOF.  Not sure the negative space on the left adds much; I''d probably crop that out.', '2011-02-07 22:40:20.000000', NULL, 1),
(6306103, 929786, 65234, '<td valign="top">With lovely little jewel-like droplets decorating them.  Love the DOF and composition.</td>', 'With lovely little jewel-like droplets decorating them.  Love the DOF and composition.', '2011-02-07 22:41:20.000000', NULL, 1),
(6306107, 929237, 65234, '<td valign="top">That looks like a fun place for a wildlife photographer!  Love the flying gulls sort of balancing the seesaw look of those poles.</td>', 'That looks like a fun place for a wildlife photographer!  Love the flying gulls sort of balancing the seesaw look of those poles.', '2011-02-07 22:43:08.000000', NULL, 1),
(6306109, 931910, 65234, '<td valign="top">Pretty, soft background is an interesting contrast to that raptor beak.</td>', 'Pretty, soft background is an interesting contrast to that raptor beak.', '2011-02-07 22:44:04.000000', NULL, 1),
(6306110, 933101, 65234, '<td valign="top">Looks kind of robotic in B&amp;W.  Excellent detail and DOF.</td>', 'Looks kind of robotic in B&W.  Excellent detail and DOF.', '2011-02-07 22:44:38.000000', NULL, 1),
(6306112, 932101, 65234, '<td valign="top">I love Wood Ducks :-)  This guy could use a little more space in the composition, I think, so he has somewhere to swim to and a smidge more headroom.</td>', 'I love Wood Ducks :-)  This guy could use a little more space in the composition, I think, so he has somewhere to swim to and a smidge more headroom.', '2011-02-07 22:45:39.000000', NULL, 1),
(6306115, 932354, 65234, '<td valign="top">Oops.  At least he''s sorta'' cute, in a baby bug kind of way.  Love his little shadow.</td>', 'Oops.  At least he''s sorta'' cute, in a baby bug kind of way.  Love his little shadow.', '2011-02-07 22:47:00.000000', NULL, 1),
(6306118, 933056, 65234, '<td valign="top">Very important to stretch before takeoff!</td>', 'Very important to stretch before takeoff!', '2011-02-07 22:48:16.000000', NULL, 1),
(6306121, 930853, 65234, '<td valign="top">Gorgeous background and nice detail on the damsel.</td>', 'Gorgeous background and nice detail on the damsel.', '2011-02-07 22:51:31.000000', NULL, 1),
(6306122, 930397, 65234, '<td valign="top">Looks nasty!</td>', 'Looks nasty!', '2011-02-07 22:51:52.000000', NULL, 1),
(6306124, 932570, 65234, '<td valign="top">Love those crossed paws :-)  And that grizzled muzzle.  Nicely composed; wish the eyes were open just a bit wider.</td>', 'Love those crossed paws :-)  And that grizzled muzzle.  Nicely composed; wish the eyes were open just a bit wider.', '2011-02-07 22:57:59.000000', NULL, 1),
(6306125, 933099, 65234, '<td valign="top">Lovely portrait of a gorgeous bird.</td>', 'Lovely portrait of a gorgeous bird.', '2011-02-07 22:59:11.000000', NULL, 1),
(6306126, 931028, 65234, '<td valign="top">Gorgeous bird!  Think I might tone down that bright branch that looks sort of like it''s growing out of his wing.</td>', 'Gorgeous bird!  Think I might tone down that bright branch that looks sort of like it''s growing out of his wing.', '2011-02-07 23:00:51.000000', NULL, 1),
(6306127, 931203, 65234, '<td valign="top">Wonderfully moody, which certainly suits the history of the place.</td>', 'Wonderfully moody, which certainly suits the history of the place.', '2011-02-07 23:01:25.000000', NULL, 1),
(6306128, 932408, 65234, '<td valign="top">Like the colors and the transition from dark to light.</td>', 'Like the colors and the transition from dark to light.', '2011-02-07 23:02:12.000000', NULL, 1),
(6306129, 931230, 65234, '<td valign="top">Just look at all the gulls!  Great job to get them all in focus; I especially love that one right in front about to lift off.  And then those two people perfectly outlined by gulls.  Really fun image!</td>', 'Just look at all the gulls!  Great job to get them all in focus; I especially love that one right in front about to lift off.  And then those two people perfectly outlined by gulls.  Really fun image!', '2011-02-07 23:05:07.000000', NULL, 1),
(6306134, 932065, 93565, '<td valign="top">Hands down the best portrait, by a good margin. Hope to see this near the top.<br/>Great posing, love the lighting.</td>', 'Hands down the best portrait, by a good margin. Hope to see this near the top.Great posing, love the lighting.', '2011-02-07 23:07:05.000000', NULL, 1),
(6306135, 933003, 65234, '<td valign="top">Love the composition on this one.  And it looks hot; I don''t blame them for finding a giraffe-sized spot of shade.</td>', 'Love the composition on this one.  And it looks hot; I don''t blame them for finding a giraffe-sized spot of shade.', '2011-02-07 23:07:12.000000', NULL, 1),
(6306136, 932581, 65234, '<td valign="top">Love the colors!</td>', 'Love the colors!', '2011-02-07 23:07:59.000000', NULL, 1),
(6306137, 932849, 65234, '<td valign="top">Yeah, good luck with that ;-)  Very cool snow formations!</td>', 'Yeah, good luck with that ;-)  Very cool snow formations!', '2011-02-07 23:08:50.000000', NULL, 1),
(6306138, 932622, 65234, '<td valign="top">Like the DOF and light.</td>', 'Like the DOF and light.', '2011-02-07 23:09:17.000000', NULL, 1),
(6306139, 928950, 65234, '<td valign="top">Nice!  I know it''s not easy to get a nice, sharp shot of jellies, even if the aquariums do try to provide nice light for them.</td>', 'Nice!  I know it''s not easy to get a nice, sharp shot of jellies, even if the aquariums do try to provide nice light for them.', '2011-02-07 23:10:06.000000', NULL, 1),
(6306143, 933037, 65234, '<td valign="top">LOL!  Great portrait and nice job on naming him.  And the border, might I add, works perfectly.</td>', 'LOL!  Great portrait and nice job on naming him.  And the border, might I add, works perfectly.', '2011-02-07 23:11:55.000000', NULL, 1),
(6306145, 927552, 65234, '<td valign="top">That looks like a really interesting place!</td>', 'That looks like a really interesting place!', '2011-02-07 23:12:18.000000', NULL, 1),
(6306149, 930463, 65234, '<td valign="top">Cool focus!  I might blur all of the non-fly parts; they''re a bit noisy and ghosted in places.</td>', 'Cool focus!  I might blur all of the non-fly parts; they''re a bit noisy and ghosted in places.', '2011-02-07 23:14:56.000000', NULL, 1),
(6306150, 933076, 54645, '<td valign="top">If only she knew. 8</td>', 'If only she knew. 8', '2011-02-07 23:16:00.000000', NULL, 1),
(6306152, 932108, 109227, '<td valign="top">I really like this image; the dof if great; could be a little sharper. Voted earlier - bumping up</td>', 'I really like this image; the dof if great; could be a little sharper. Voted earlier - bumping up', '2011-02-07 23:16:38.000000', NULL, 1),
(6306154, 931035, 65234, '<td valign="top">I love the contemplative feel to this.  Beautifully composed and just enough detail to lend some substance to the dreaminess.</td>', 'I love the contemplative feel to this.  Beautifully composed and just enough detail to lend some substance to the dreaminess.', '2011-02-07 23:17:34.000000', NULL, 1),
