(6306158, 931140, 109227, '<td valign="top">Looks like he is sliding downhill, lol.  Nice capture.Cardinals are beautiful against the snow.  voted earlier</td>', 'Looks like he is sliding downhill, lol.  Nice capture.Cardinals are beautiful against the snow.  voted earlier', '2011-02-07 23:19:57.000000', NULL, 1),
(6306161, 931073, 83313, '<td valign="top">Not my personal taste, but I can still appreciate a well done shot. The guy doing a double take in the background is a great touch.</td>', 'Not my personal taste, but I can still appreciate a well done shot. The guy doing a double take in the background is a great touch.', '2011-02-07 23:20:44.000000', NULL, 1),
(6306162, 931878, 109227, '<td valign="top">What''s not to like about this one.  Mom doesn''t look too happy.  Great capture. voted earlier</td>', 'What''s not to like about this one.  Mom doesn''t look too happy.  Great capture. voted earlier', '2011-02-07 23:20:46.000000', NULL, 1),
(6306165, 932570, 109227, '<td valign="top">Looks like a gentleman with the perfect pose.  Great detail in the coat.  voted earlier.</td>', 'Looks like a gentleman with the perfect pose.  Great detail in the coat.  voted earlier.', '2011-02-07 23:22:13.000000', NULL, 1),
