(6306167, 932878, 109227, '<td valign="top">I like the DOF on ths one.  The lighting is just right. voted earlier</td>', 'I like the DOF on ths one.  The lighting is just right. voted earlier', '2011-02-07 23:24:29.000000', NULL, 1),
(6306169, 931580, 30982, '<td valign="top">I love how this slowly appears as you watch... then just as quietly recedes.</td>', 'I love how this slowly appears as you watch... then just as quietly recedes.', '2011-02-07 23:25:34.000000', NULL, 1),
(6306170, 932966, 109227, '<td valign="top">Beautiful cat; nicely done.  voted earlier</td>', 'Beautiful cat; nicely done.  voted earlier', '2011-02-07 23:25:50.000000', NULL, 1),
(6306176, 932800, 30982, '<td valign="top">Great snowman!  Kudos to the builders, and a nice shot of the guy!</td>', 'Great snowman!  Kudos to the builders, and a nice shot of the guy!', '2011-02-07 23:32:29.000000', NULL, 1),
(6306180, 931734, 30982, '<td valign="top">I think she means it, too.  I like how the crack in the pavement almost looks like the stick you put a woody on.  But she doesn''t look at all like a woody.  :-)  Fun shot!</td>', 'I think she means it, too.  I like how the crack in the pavement almost looks like the stick you put a woody on.  But she doesn''t look at all like a woody.  :-)  Fun shot!', '2011-02-07 23:33:36.000000', NULL, 1),
(6306184, 931093, 54645, '<td valign="top">Ha! Not often you see horses posing nude in the snow. Took me all week to finish your <strike>novel</strike> title.</td>', 'Ha! Not often you see horses posing nude in the snow. Took me all week to finish your novel title.', '2011-02-07 23:36:40.000000', NULL, 1),
(6306205, 931035, 62357, '<td valign="top">Somehow I''m not surprised this is yours Ben.  It seems you are fast becoming my statistically favourite photographer.  This is delightful and happy to see so many others thought so too.  Well done a such a high score</td>', 'Somehow I''m not surprised this is yours Ben.  It seems you are fast becoming my statistically favourite photographer.  This is delightful and happy to see so many others thought so too.  Well done a such a high score', '2011-02-08 00:03:22.000000', NULL, 0),
(6306206, 931073, 30861, '<td valign="top">That''s a stupid finish. I thought this was great, with the double-take and all. Gave it a 9. I''m sure it''s the highest score you ever got from me :-)</td>', 'That''s a stupid finish. I thought this was great, with the double-take and all. Gave it a 9. I''m sure it''s the highest score you ever got from me :-)', '2011-02-08 00:03:32.000000', NULL, 0),
