(6306211, 931805, 62357, '<td valign="top">Marla, I suppose 5.2 is a good score for a pinhole.  Check out your commenter''s score!  Ha.<br/><br/><i>Message edited by author 2011-02-08 23:07:03.</i></td>', 'Marla, I suppose 5.2 is a good score for a pinhole.  Check out your commenter''s score!  Ha.', '2011-02-08 00:07:04.000000', '2011-02-08 23:07:03.000000', 0),
