(6306221, 932860, 30982, '<td valign="top">I thought this might be yours due to the subject matter.  The technicals and feel of this really show how far you''ve advanced since you joined up here.  Very professional!</td>', 'I thought this might be yours due to the subject matter.  The technicals and feel of this really show how far you''ve advanced since you joined up here.  Very professional!', '2011-02-08 00:14:08.000000', NULL, 0),
(6306222, 932108, 68504, '<td valign="top">This works on many levels.  I don''t think I would ever get tired looking at it.</td>', 'This works on many levels.  I don''t think I would ever get tired looking at it.', '2011-02-08 00:14:16.000000', NULL, 0),
(6306223, 931035, 12253, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2011-02-08 00:14:46.000000', NULL, 0),
(6306224, 932708, 51747, '<td valign="top">Very nice shot. The arches and ceiling are wonderful. I recognized this spot immediately. Scored a 7 from me.<br/><br/><i>Message edited by author 2011-02-08 07:50:22.</i></td>', 'Very nice shot. The arches and ceiling are wonderful. I recognized this spot immediately. Scored a 7 from me.', '2011-02-08 00:15:21.000000', '2011-02-08 07:50:22.000000', 0),
(6306225, 930396, 30982, '<td valign="top">The background is the background - serves a marvelous purpose of just being there (and it is not at all distracting) to support the marvelous face in the foreground!  Your chops are just fine.</td>', 'The background is the background - serves a marvelous purpose of just being there (and it is not at all distracting) to support the marvelous face in the foreground!  Your chops are just fine.', '2011-02-08 00:15:22.000000', NULL, 0),
