(6306227, 931045, 30982, '<td valign="top">I gotta get my phone out more often.  This scored well with me.  Great wintery feel from the warmth of inside the car.  Nice!</td>', 'I gotta get my phone out more often.  This scored well with me.  Great wintery feel from the warmth of inside the car.  Nice!', '2011-02-08 00:16:44.000000', NULL, 0),
(6306229, 932046, 12253, '<td valign="top">Very nice photo--should have finished much higher, but at least you were over 6!</td>', 'Very nice photo--should have finished much higher, but at least you were over 6!', '2011-02-08 00:17:18.000000', NULL, 0),
(6306230, 928950, 68504, '<td valign="top">Very nice!</td>', 'Very nice!', '2011-02-08 00:17:25.000000', NULL, 0),
