(6306241, 930749, 83313, '<td valign="top">You kicked butt again. It''s getting hard to stay ahead of you!</td>', 'You kicked butt again. It''s getting hard to stay ahead of you!', '2011-02-08 00:19:20.000000', NULL, 0),
