(6306247, 931035, 30982, '<td valign="top">The accolades are more than well deserved, Doc Ben.  You do amazing work.</td>', 'The accolades are more than well deserved, Doc Ben.  You do amazing work.', '2011-02-08 00:21:09.000000', NULL, 0),
