(6306414, 932897, 96751, '<td valign="top">So, now it''s a house boat.  I love the colors.</td>', 'So, now it''s a house boat.  I love the colors.', '2011-02-08 01:43:24.000000', NULL, 0),
(6306415, 933115, 54645, '<td valign="top">I spent quite some time with this. Gave you an 8. I find the perception of space/distance confounding, and this is the strength of the image. She has been distorted in size and motion, what a trip.</td>', 'I spent quite some time with this. Gave you an 8. I find the perception of space/distance confounding, and this is the strength of the image. She has been distorted in size and motion, what a trip.', '2011-02-08 01:43:32.000000', NULL, 0),
